// FLIP and WWXRP amounts at the chain boundary.
//
// Inside the site every FLIP and WWXRP amount is TOKEN WEI: 10^18 per token, the unit the
// formatters (scaling.js displayToken, the panels' own helpers) and every constant were written
// in. The chain's own unit depends on the deployment. Audit b05ea7c50 (run 64) made both tokens
// zero-decimal: one raw unit is one whole token in balances, allowances, transfers, events, view
// results, storage and every function argument (degenerus-audit docs/TOKEN-UNITS.md). Older
// deployments (run 63 and before) used 18 decimals. So:
//   - a FLIP/WWXRP amount READ from the chain (call result, storage, event arg) goes through
//     flipFromChain() before anything else sees it;
//   - a FLIP/WWXRP amount SENT to the chain (tx or staticCall argument, packed calldata) goes
//     through flipToChain()/flipToChainCeil() as the last step.
// ETH, stETH, LINK, DGNRS, sDGNRS, GNRUS and vault shares are 18 decimals everywhere and never
// pass through here. Internal 10^18 sub-units the contracts keep for math (the Decimator
// normalized peak, box/foil spin stakes, the craps simulation) are not token amounts either.
import { hasWholeTokens } from '../chain/schema.js';

/** The site's internal FLIP/WWXRP unit: 10^18 token wei per token. */
export const TOKEN_WEI = 10n ** 18n;

/** Raw on-chain units per whole FLIP or WWXRP on the active deployment (1n, or 10^18 before run 64). */
export function chainTokenUnit() { return hasWholeTokens() ? 1n : TOKEN_WEI; }

/** Token wei per raw on-chain unit (10^18 for whole-token deployments, 1 before run 64). */
function weiPerRaw() { return hasWholeTokens() ? TOKEN_WEI : 1n; }

/** A FLIP/WWXRP amount read from the chain, as token wei. */
export function flipFromChain(raw) { return BigInt(raw ?? 0) * weiPerRaw(); }

/** String form of flipFromChain, for the API-shaped rows the panels consume. */
export function flipStringFromChain(raw) { return String(flipFromChain(raw)); }

/**
 * A FLIP/WWXRP amount in token wei, as the raw chain argument. Floors: a whole-token deployment
 * cannot take a fraction, and spending less than the player typed never overdraws them. Inputs
 * that must reach a minimum use flipToChainCeil, and parsers should reject fractions first
 * (isWholeTokenAmount).
 */
export function flipToChain(wei) {
  const value = BigInt(wei ?? 0);
  return value / weiPerRaw();
}

/** As flipToChain but rounds a fraction UP (a charge or minimum that must be covered). */
export function flipToChainCeil(wei) {
  const value = BigInt(wei ?? 0); const scale = weiPerRaw();
  return value <= 0n ? value / scale : (value + scale - 1n) / scale;
}

/** True when `wei` is representable on the active deployment without rounding. */
export function isWholeTokenAmount(wei) {
  return BigInt(wei ?? 0) % weiPerRaw() === 0n;
}

/** The deployment's FLIP/WWXRP decimals (0 from run 64, 18 before). */
export function chainTokenDecimals() { return hasWholeTokens() ? 0 : 18; }

// ---------------------------------------------------------------------------
// Decoded chain values. Every FLIP/WWXRP amount field below changed from 18-decimal raw units
// (run 63, audit 95d88f68b) to whole tokens (audit b05ea7c50, verified against eb04b2e80). The
// chain layer (app/chain/client.js decodeLog, ChainSnapshot.call) multiplies exactly these by
// 10^18 on a whole-token deployment, so every reader and panel keeps seeing token wei. A field
// that was already whole-FLIP before (a score kept in whole tokens, a packed whole-FLIP lane) is
// NOT listed: it reads the same on both. A value that is FLIP only for some rows names a
// predicate over the decoded args. Keys are `CONTRACT.name`, CONTRACT as in chain-config.
// ---------------------------------------------------------------------------
const always = true;

/** DegenerusQuests types whose progress and targets are FLIP amounts: FLIP stake (2), affiliate
 *  (3), Decimator (5) and FLIP Degenerette (8). ETH types are wei; mint/foil/craps are counts. */
export const FLIP_QUEST_TYPES = Object.freeze([2, 3, 5, 8]);
export const isFlipQuestType = type => FLIP_QUEST_TYPES.includes(Number(type));

/** BoxSpin.betId bits 60..62 (DegeneretteModule._boxBetId): 0 WWXRP, 1 FLIP, 2 ETH, 3 record (FLIP). */
export const boxSpinType = betId => Number((BigInt(betId ?? 0) >> 60n) & 7n);
const tokenBoxSpin = args => boxSpinType(args.betId) !== 2;

