function scaledView(result, params, spec, args) {
  const overrides = new Map(); const scale = weiPerRaw();
  params.forEach((param, i) => {
    const rule = spec[param.name] ?? spec[String(i)];
    if (!rule || (typeof rule === 'function' && !rule(args))) return;
    overrides.set(i, BigInt(result[i]) * scale);
  });
  if (!overrides.size) return result;
  // An ethers Result is frozen (a Proxy cannot answer for its fixed slots), so build the same
  // shape: positional values, named values as own properties, and toObject().
  const out = Array.from({ length: params.length }, (_, i) => (overrides.has(i) ? overrides.get(i) : result[i]));
  const named = {};
  params.forEach((param, i) => {
    if (!param.name) return;
    named[param.name] = out[i];
    Object.defineProperty(out, param.name, { value: out[i], enumerable: false });
  });
  Object.defineProperty(out, 'toObject', { value: () => ({ ...named }), enumerable: false });
  return out;
}

/** Rescale a decoded event's FLIP/WWXRP args to token wei (identity before run 64). */
export function scaleDecodedEvent(contract, fragment, args) {
  const spec = contract && hasWholeTokens() ? WHOLE_TOKEN_EVENT_FIELDS[`${contract}.${fragment.name}`] : null;
  return spec ? scaledView(args, fragment.inputs, spec, args) : args;
}

/** Rescale a decoded call result's FLIP/WWXRP outputs to token wei (identity before run 64). */
export function scaleCallResult(contract, fragment, result) {
  const spec = contract && hasWholeTokens() ? WHOLE_TOKEN_CALL_FIELDS[`${contract}.${fragment.name}`] : null;
  return spec ? scaledView(result, fragment.outputs, spec, result) : result;
}
